UPDATE content_pages p
  JOIN content_items ci ON ci.id = p.content_item_id
   SET p.body_en = '<h2>President Message</h2><p></p>

<p> </p>

<p><strong>Respected Members</strong> </p>

<p>First of all I am thankful to Allah, the Almighty, for giving me this great honor. I also want to thank you all for reposing your confidence in me. It is a great honor as well as a big responsibility. </p>

<p>I acknowledge the good efforts of my predecessors for the betterment of the Chamber and their contribution to highlight the problems of business community at all forums. I would take forward their good work.</p>

<p>I have assumed this position with a strong commitment to serve the business community and make best efforts for resolving key issues being faced by trade and industry. For this purpose, I would try to develop close liaison with all stakeholder organizations to facilitate growth of trade and Industry.</p>

<p>We must understand that dynamics of the business are changing fast. Therefore, I would request LCCI members to keep sending us proposals and suggestions for improving our services .Your recommendations and support would enable us to achieve standard of excellence in working and making the Chamber a stronger platform.</p>

<p>I assure that with the blessings of Allah, the Almighty, and your cooperation, we shall be able to play our role effectively.</p>

<p>                                                                                   </p>

<p>         <strong> Mr. Ali Hussam Asghar</strong></p>

<p>                                                                                                                       <strong>President LCCI</strong></p>'
 WHERE ci.content_type = 'page'
   AND ci.slug = 'about-leadership'
   AND p.body_en IS NULL;

UPDATE content_items
   SET status = 'published', published_at = '2026-10-01 05:00:00.000'
 WHERE content_type = 'page' AND slug = 'about-leadership'
   AND status = 'draft'
   AND EXISTS (
     SELECT 1 FROM content_pages p
      WHERE p.content_item_id = content_items.id AND p.body_en IS NOT NULL
   );

